package org.sigf.ui;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.FileChooser;
import java.time.*;
import java.util.*;
import java.math.BigDecimal;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import org.sigf.config.Database;
import org.sigf.security.Security;
import org.sigf.repositories.ReportRepository;
import org.sigf.domain.ReportGrid;

public final class ReportsPane extends VBox {
 private final ReportRepository repository;private final ComboBox<String> type=new ComboBox<>();private final Map<String,String> types=new LinkedHashMap<>();private final DatePicker from=new DatePicker(LocalDate.now().withDayOfMonth(1)),to=new DatePicker(LocalDate.now());private final TextField search=new TextField();private final TableView<List<String>> table=Views.table("Sin resultados para estos filtros");private final Label status=new Label(),pageLabel=new Label(),count=new Label(),amount=new Label(),voided=new Label();private int page,version;private long total;private final Button previous,next;private String appliedType="stock",appliedSearch="";private LocalDate appliedFrom,appliedTo;private ReportGrid current;
 public ReportsPane(Database db,Security.User user){repository=new ReportRepository(db);getStyleClass().add("workspace");setSpacing(16);Views.date(from);Views.date(to);types.put("Existencias","stock");types.put("Ventas por período","sales");types.put("Compras","purchases");types.put("Productos más vendidos","top");types.put("Vencimientos","batches");types.put("Movimientos de inventario","movements");types.put("Resumen de IVA","tax_summary");types.put("Comprobantes internos","internal_docs");types.put("Anulaciones internas","voided_docs");if(user.role().equals("ADMIN")){types.put("Actividad administrativa","audit");types.put("Conciliación de datos","reconciliation");}type.getItems().addAll(types.keySet());type.setValue("Existencias");type.setId("reportType");search.setPromptText("Buscar en todo el reporte");search.setPrefWidth(230);
  Button consult=Views.button("Consultar","search",()->{try{from.commitValue();to.commitValue();}catch(Exception ex){status.setText("Fecha inválida. Usa DD/MM/AAAA");return;}page=0;appliedType=types.get(type.getValue());appliedFrom=from.getValue();appliedTo=to.getValue();appliedSearch=search.getText();load();},true);consult.setId("reportConsult");search.setOnAction(e->consult.fire());type.setOnAction(e->{boolean dates=!Set.of("stock","reconciliation").contains(types.get(type.getValue()));from.setDisable(!dates);to.setDisable(!dates);status.setText("Pulsa Consultar para aplicar los filtros");});from.setDisable(true);to.setDisable(true);
  FlowPane presets=new FlowPane(6,6,Views.button("Hoy","calendar",()->period(LocalDate.now(),LocalDate.now()),false),Views.button("Ayer","calendar",()->period(LocalDate.now().minusDays(1),LocalDate.now().minusDays(1)),false),Views.button("Esta semana","calendar",()->period(LocalDate.now().with(java.time.DayOfWeek.MONDAY),LocalDate.now()),false),Views.button("Este mes","calendar",()->period(LocalDate.now().withDayOfMonth(1),LocalDate.now()),false));FlowPane filters=new FlowPane(10,10,type,new Label("Desde"),from,new Label("Hasta"),to,Views.searchBox(search,"search"),consult);
  MenuButton export=new MenuButton("Exportar",UiIcons.icon("export","action-icon",20));MenuItem all=new MenuItem("Reporte completo con los filtros aplicados",UiIcons.icon("file","action-icon",20)),visible=new MenuItem("Solo página visible",UiIcons.icon("file","action-icon",20));all.setOnAction(e->export(false));visible.setOnAction(e->export(true));export.getItems().addAll(all,visible);
  HBox summary=new HBox(14,Views.cardWithIcon("Resultados","Reportes",count),Views.cardWithIcon("Importe del reporte","cash",amount),Views.cardWithIcon("Anuladas","close",voided));for(var node:summary.getChildren())HBox.setHgrow(node,Priority.ALWAYS);count.getStyleClass().add("sale-total");amount.getStyleClass().add("sale-total");voided.getStyleClass().add("sale-total");previous=Views.button("Anterior","chevron-left",()->{if(page>0){page--;load();}},false);next=Views.button("Siguiente","chevron-right",()->{if((page+1L)*50<total){page++;load();}},false);HBox paging=new HBox(12,previous,pageLabel,next);VBox card=Views.cardWithIcon("Resultado de la consulta","file",table,paging);VBox.setVgrow(table,Priority.ALWAYS);VBox.setVgrow(card,Priority.ALWAYS);getChildren().addAll(Views.headerWithIcon("Reportes","Consulta, compara y exporta información con filtros claros","Reportes",export),Views.cardWithIcon("Filtros","filter",presets,filters),summary,card,status);appliedFrom=from.getValue();appliedTo=to.getValue();load();
 }
 private void period(LocalDate a,LocalDate b){from.setValue(a);to.setValue(b);status.setText("Período seleccionado. Pulsa Consultar.");}
 private record Result(ReportGrid page,ReportGrid summary){}
 private void load(){current=null;count.setText("—");amount.setText("—");voided.setText("—");previous.setDisable(true);next.setDisable(true);int ticket=++version;String name=appliedType,q=appliedSearch;LocalDate a=appliedFrom,b=appliedTo;int offset=page*50;status.setText("Consultando…");Views.async(()->new Result(repository.reportSearch(name,a,b,offset,50,q),repository.summary(name,a,b,q)),result->{if(ticket!=version)return;current=result.page();Views.grid(table,current);var values=result.summary().rows().getFirst();total=Long.parseLong(values.get(0));count.setText(Long.toString(total));amount.setText(values.get(1).isBlank()?"No aplica":Views.money(new BigDecimal(values.get(1))));voided.setText(values.get(2));pageLabel.setText("Página "+(page+1)+" de "+Math.max(1,(total+49)/50));previous.setDisable(page==0);next.setDisable((page+1L)*50>=total);status.setText((Set.of("stock","reconciliation").contains(name)?"Situación actual":"Del "+a+" al "+b)+" · "+total+" resultados · filtros aplicados");},ex->{if(ticket==version){current=null;table.getItems().clear();status.setText("No se pudo consultar: "+ex.getMessage());}});}
 private void export(boolean pageOnly){if(current==null){Views.error(new IllegalStateException("Consulta un reporte antes de exportar"));return;}FileChooser chooser=new FileChooser();chooser.setTitle("Exportar CSV");chooser.setInitialFileName("sigf-"+appliedType+"-"+LocalDate.now()+".csv");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("CSV","*.csv"));var file=chooser.showSaveDialog(getScene().getWindow());if(file==null)return;String name=appliedType,q=appliedSearch;LocalDate a=appliedFrom,b=appliedTo;ReportGrid snapshot=current;status.setText("Exportando…");Views.async(()->{ReportGrid grid=pageOnly?snapshot:repository.reportSearch(name,a,b,0,0,q);try(var writer=Files.newBufferedWriter(file.toPath(),StandardCharsets.UTF_8)){writer.write(csv(grid.columns()));writer.newLine();for(var row:grid.rows()){writer.write(csv(row));writer.newLine();}}return null;},x->status.setText("Reporte exportado: "+file.getName()),Views::error);}
 private static String csv(List<String> values){return values.stream().map(v->"\""+((!v.isEmpty()&&"=+-@".indexOf(v.charAt(0))>=0)?"'":"")+v.replace("\"","\"\"")+"\"").collect(java.util.stream.Collectors.joining(","));}
 public void reload(){load();}
}
